def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)

def safe_native_error(body, secrets=()):
    """Bound and redact error DATA; never persist the full native body."""
    nodes = [body]
    if isinstance(body, dict):
        nodes = [body, body.get("error"), body.get("structuredContent")]
        content = body.get("content")
        for item in (content[:8] if isinstance(content, list) else []):
            if isinstance(item, dict) and item.get("type") == "text":
                nodes.append(item.get("text"))
    code, message, complete = None, None, False
    for node in nodes:
        if isinstance(node, str):
            if len(node) > 8192:
                message, complete = None, False
                break
            head = node
            if head.startswith(("brain_remember failed: ", "brain_get failed: ")) and "{" in head:
                head = head[head.index("{"):]
            try:
                parsed = json.loads(head)
            except ValueError:
                parsed = None
            if isinstance(parsed, dict):
                node = parsed
            else:
                message, complete = head, True
                break
        if isinstance(node, dict):
            if isinstance(node.get("error"), str):
                value, code = node["error"], node.get("code")
                if len(value) > 8192:
                    message, complete = None, False
                else:
                    message, complete = value, True
                break
            if isinstance(node.get("error"), dict):
                node = node["error"]
            code = node.get("code")
            value = node.get("message")
            if isinstance(value, str):
                code = node.get("code")
                if len(value) > 8192:
                    message, complete = None, False
                else:
                    message, complete = value, True
                break
            if code is not None:
                message, complete = None, False
                break
    def scrub(value, limit):
        text = str(value)
        for secret in secrets:
            if secret:
                text = text.replace(secret, "[REDACTED]")
        text = re.sub(r"([a-zA-Z][a-zA-Z0-9+.-]*://)[^/\s@]+@", r"\1[REDACTED]@", text)
        text = re.sub(r"(?i)\b(?:authorization|proxy-authorization)\b[\s\"':=]+(?:bearer|basic)?\s*[^\s,;]+", "Authorization=[REDACTED]", text)
        text = re.sub(r"(?i)\b(?:bearer|basic)\s+[^\s,;]+", "Bearer [REDACTED]", text)
        text = re.sub(r"(?i)\b(?:token|access_token|api[_-]?key|password|secret)\b[\s\"':=]+[^\s\",;]+", "secret=[REDACTED]", text)
        text = re.sub(r"(?<![:\w])/(?:[^\s\"',;]+)", "[REDACTED_PATH]", text)
        text = re.sub(r"[\x00-\x1f\x7f-\x9f]", " ", text)
        return text[:limit], len(text) <= limit
    message, bounded = scrub(message, 1024) if message is not None else (None, False)
    if isinstance(code, str) and len(code) > 256:
        code, complete = None, False
    code = scrub(code, 80)[0] if type(code) in (str, int) else None
    return {"code": code, "message": message, "complete": complete and bounded}


class NativeError(RuntimeError):
    def __init__(self, body):
        self.body = body
        super().__init__("Native Brain rejected call: " + record_digest(body))


